  - intros t Ht p _. apply fire_1RB1LB_0LC1RB_1RA1LD_1LC0RB. exact Ht.
  - exact wit_1RB1LB_0LC1RB_1RA1LD_1LC0RB.
  - apply qcleb_QC_20. reflexivity.
