  apply (fire_of_run_instr tm Cc true true l B0_1RB1LB_0RC1LB_1LA1RD_1RC0LB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LB_0RC1LB_1LA1RD_1RC0LB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
