Lemma firei_1RB1LB_0RC1LB_1LA1RD_1RC0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LB_0RC1LB_1LA1RD_1RC0LB = Some t ->
